import heapq


def min_cost_route(n, edges, s, t, switch_cost):
    if s == t:
        return 0

    # State (v, c) means we are at node v and the previous edge had color c.
    color_to_id = {}
    states_at = [dict() for _ in range(n)]  # node -> {color_id: state_id}
    colored_edges = []
    state_count = 0

    for u, v, w, color in edges:
        color_id = color_to_id.get(color)
        if color_id is None:
            color_id = len(color_to_id)
            color_to_id[color] = color_id

        for node in (u, v):
            node_states = states_at[node]
            if color_id not in node_states:
                node_states[color_id] = state_count
                state_count += 1

        colored_edges.append((u, v, w, color_id))

    # One auxiliary hub per original node compresses all color switches.
    graph = [[] for _ in range(state_count + n)]

    for node, node_states in enumerate(states_at):
        hub = state_count + node
        for state in node_states.values():
            graph[state].append((hub, 0))
            graph[hub].append((state, switch_cost))

    # Traversing an undirected edge preserves the current color state.
    for u, v, w, color_id in colored_edges:
        state_u = states_at[u][color_id]
        state_v = states_at[v][color_id]
        graph[state_u].append((state_v, w))
        graph[state_v].append((state_u, w))

    # The first edge has no switch charge, so every initial color is allowed.
    INF = 10**30
    dist = [INF] * len(graph)
    heap = []

    for state in states_at[s].values():
        dist[state] = 0
        heap.append((0, state))

    heapq.heapify(heap)

    while heap:
        current_dist, state = heapq.heappop(heap)
        if current_dist != dist[state]:
            continue

        for next_state, edge_cost in graph[state]:
            new_dist = current_dist + edge_cost
            if new_dist < dist[next_state]:
                dist[next_state] = new_dist
                heapq.heappush(heap, (new_dist, next_state))

    answer = min(
        (dist[state] for state in states_at[t].values()),
        default=INF,
    )
    return -1 if answer == INF else answer

class RateLimiter:
    def __init__(self, max_calls, window_seconds):
        self.max_calls = max_calls
        self.window = window_seconds
        self.calls = []

    def allow(self, timestamp):
        self.calls = [t for t in self.calls if timestamp - t < self.window]
        if len(self.calls) < self.max_calls:
            self.calls.append(timestamp)
            return True
        return False

def merge_settings(defaults, overrides):
    result = dict(defaults)
    for key, value in overrides.items():
        if isinstance(value, dict) and isinstance(result.get(key), dict):
            result[key] = merge_settings(result[key], value)
        else:
            result[key] = value
    return result

def purge_expired(sessions, now):
    purged = []
    for sid, expiry in list(sessions.items()):
        if expiry <= now:
            del sessions[sid]
            purged.append(sid)
    return purged

def insert_booking(bookings, new):
    start, end = new
    if start >= end:
        raise ValueError("empty booking")
    result = []
    i = 0
    while i < len(bookings) and bookings[i][1] <= start:
        result.append(bookings[i])
        i += 1
    while i < len(bookings) and bookings[i][0] < end:
        start = min(start, bookings[i][0])
        end = max(end, bookings[i][1])
        i += 1
    result.append((start, end))
    result.extend(bookings[i:])
    return result

from collections import deque


def min_steps(grid, c):
    R = len(grid)
    C = len(grid[0])

    if grid[0][0] == -1 or grid[R - 1][C - 1] == -1:
        return -1

    directions = ((1, 0), (-1, 0), (0, 1), (0, -1))

    def walking_distances(start_r, start_c):
        dist = [[-1] * C for _ in range(R)]
        dist[start_r][start_c] = 0
        queue = deque([(start_r, start_c)])

        while queue:
            r, col = queue.popleft()
            next_dist = dist[r][col] + 1

            for dr, dc in directions:
                nr, nc = r + dr, col + dc
                if (
                    0 <= nr < R
                    and 0 <= nc < C
                    and grid[nr][nc] != -1
                    and dist[nr][nc] == -1
                ):
                    dist[nr][nc] = next_dist
                    queue.append((nr, nc))

        return dist

    from_start = walking_distances(0, 0)
    to_goal = walking_distances(R - 1, C - 1)

    # For each label, retain:
    # - the cheapest walking cost from the start to a teleport source
    # - the cheapest walking cost from a teleport destination to the goal
    best_before = {}
    best_after = {}

    for r in range(R):
        for col in range(C):
            label = grid[r][col]
            if label == -1:
                continue

            d = from_start[r][col]
            if d != -1 and (label not in best_before or d < best_before[label]):
                best_before[label] = d

            d = to_goal[r][col]
            if d != -1 and (label not in best_after or d < best_after[label]):
                best_after[label] = d

    # Option 1: never teleport.
    answer = from_start[R - 1][C - 1]

    # Option 2: walk, teleport once between cells with the same label, then walk.
    for label, before_cost in best_before.items():
        after_cost = best_after.get(label)
        if after_cost is None:
            continue

        candidate = before_cost + c + after_cost
        if answer == -1 or candidate < answer:
            answer = candidate

    return answer

def resolve_build_order(deps):
    graph = {}
    for pkg, ds in deps.items():
        graph.setdefault(pkg, [])
        for d in ds:
            graph.setdefault(d, [])
            if d not in graph[pkg]:   # treat duplicate entries as one dependency
                graph[pkg].append(d)
    order = []
    visiting = set()  # nodes on the current DFS path (gray)
    visited = set()   # nodes fully processed (black)

    def visit(node):
        if node in visited:
            return                       # shared dependency: fine, not a cycle
        if node in visiting:
            raise ValueError("dependency cycle detected at " + node)
        visiting.add(node)
        for dep in sorted(graph[node]):
            visit(dep)
        visiting.discard(node)           # backtrack: node no longer on the path
        visited.add(node)
        order.append(node)

    for node in sorted(graph):
        if node not in visited:
            visit(node)
    return order

class UndoStack:
    def __init__(self):
        self._items = []
        self._history = []

    def push(self, x) -> None:
        self._items.append(x)
        self._history.append(("push",))

    def pop(self):
        if not self._items:
            raise IndexError("pop from empty stack")

        value = self._items.pop()
        self._history.append(("pop", value))
        return value

    def peek(self):
        if not self._items:
            raise IndexError("peek from empty stack")

        return self._items[-1]

    def undo(self) -> None:
        if not self._history:
            raise RuntimeError("nothing to undo")

        operation, *args = self._history.pop()

        if operation == "push":
            self._items.pop()
        else:
            value = args[0]
            self._items.append(value)

    def __len__(self) -> int:
        return len(self._items)

import re

_AMOUNT_RE = re.compile(r"([0-9]+)(?:\.([0-9]{1,2}))?")

def compute_balances(transactions):
    balances = {}
    for tx in transactions:
        amount = tx["amount"]
        m = _AMOUNT_RE.fullmatch(amount)
        if m is None:
            raise ValueError(f"invalid amount: {amount!r}")
        cents = int(m.group(1)) * 100
        if m.group(2) is not None:
            cents += int(m.group(2).ljust(2, "0"))
        if cents <= 0:
            raise ValueError(f"amount must be positive: {amount!r}")
        balances[tx["from"]] = balances.get(tx["from"], 0) - cents
        balances[tx["to"]] = balances.get(tx["to"], 0) + cents
    return balances

def apply_hunks(lines, hunks):
    ordered = sorted(hunks, key=lambda h: h[0])
    for i in range(1, len(ordered)):
        prev = ordered[i - 1]
        curr = ordered[i]
        if curr[0] == prev[0] or curr[0] < prev[0] + prev[1]:
            raise ValueError("conflicting hunks")
    for start, delete, insert in ordered:
        if start < 0 or start + delete > len(lines):
            raise ValueError("hunk out of range")
    result = list(lines)
    for start, delete, insert in reversed(ordered):
        result[start:start + delete] = list(insert)
    return result

from collections import OrderedDict


class TTLCache:
    """Fixed-capacity LRU cache with per-entry TTL on an explicit logical clock."""

    def __init__(self, capacity):
        if not isinstance(capacity, int) or capacity < 1:
            raise ValueError("capacity must be an integer >= 1")
        self._capacity = capacity
        # key -> (value, stored_time, ttl); OrderedDict order is LRU -> MRU
        self._entries = OrderedDict()
        self._hits = 0
        self._misses = 0
        self._evictions = 0
        self._expirations = 0

    def _purge(self, now):
        """Remove every entry dead at `now`, counting them as expirations."""
        dead = [
            key
            for key, (_, stored_at, ttl) in self._entries.items()
            if ttl is not None and now >= stored_at + ttl
        ]
        for key in dead:
            del self._entries[key]
        self._expirations += len(dead)

    def put(self, key, value, now, ttl=None):
        if ttl is not None and ttl <= 0:
            raise ValueError("ttl must be a positive number or None")
        self._purge(now)
        if key in self._entries:
            # Update in place: refresh value, timestamp, ttl, and recency.
            self._entries[key] = (value, now, ttl)
            self._entries.move_to_end(key)
            return
        if len(self._entries) >= self._capacity:
            self._entries.popitem(last=False)  # evict LRU
            self._evictions += 1
        self._entries[key] = (value, now, ttl)

    def get(self, key, now):
        self._purge(now)
        if key in self._entries:
            self._hits += 1
            self._entries.move_to_end(key)
            return self._entries[key][0]
        self._misses += 1
        return None

    def stats(self):
        return {
            "hits": self._hits,
            "misses": self._misses,
            "evictions": self._evictions,
            "expirations": self._expirations,
        }

    def __len__(self):
        return len(self._entries)

class Leaderboard:
    """Tracks each player's best score with first-achievement tie-breaking."""

    def __init__(self):
        # player -> (best_score, sequence_number_when_that_best_was_set)
        self._best = {}
        self._clock = 0

    def submit(self, player, score):
        """Record an attempt. Return True only if it strictly improves the
        player's best (or the player is new); otherwise change nothing."""
        entry = self._best.get(player)
        if entry is None or score > entry[0]:
            self._best[player] = (score, self._clock)
            self._clock += 1
            return True
        return False

    def best(self, player):
        """Return the player's best score; KeyError if unknown."""
        if player not in self._best:
            raise KeyError(player)
        return self._best[player][0]

    def rank(self, player):
        """Standard competition ranking: 1 + number of strictly better players."""
        if player not in self._best:
            raise KeyError(player)
        pbest = self._best[player][0]
        return 1 + sum(1 for s, _ in self._best.values() if s > pbest)

    def top(self, k):
        """Top k (player, best) tuples: score descending, ties by earliest
        achievement of that best."""
        if k < 0:
            raise ValueError("k must be non-negative")
        ordered = sorted(
            self._best.items(),
            key=lambda item: (-item[1][0], item[1][1]),
        )
        return [(player, score) for player, (score, _) in ordered[:k]]

    def player_count(self):
        return len(self._best)

