import itertools


class TaskScheduler:
    """Priority queue of unique task ids.

    Higher priority is served first; ties are broken by the original
    submission order (reprioritizing does not change FIFO position).
    """

    def __init__(self):
        self._heap = []                        # entries: (-priority, seq, task_id)
        self._tasks = {}                       # task_id -> (priority, seq)
        self._seq = itertools.count()          # submission-order counter

    def submit(self, task_id, priority):
        if task_id in self._tasks:
            raise ValueError(f"task {task_id!r} is already active")
        seq = next(self._seq)
        self._tasks[task_id] = (priority, seq)
        heapq.heappush(self._heap, (-priority, seq, task_id))

    def reprioritize(self, task_id, priority):
        try:
            _, seq = self._tasks[task_id]      # keep the ORIGINAL seq
        except KeyError:
            raise KeyError(task_id) from None
        self._tasks[task_id] = (priority, seq)
        heapq.heappush(self._heap, (-priority, seq, task_id))  # old entry becomes stale

    def cancel(self, task_id):
        try:
            del self._tasks[task_id]           # its heap entry becomes stale
        except KeyError:
            raise KeyError(task_id) from None

    def _purge(self):
        """Discard stale heap entries until the top is current (or heap empty)."""
        heap, tasks = self._heap, self._tasks
        while heap:
            neg_pri, seq, task_id = heap[0]
            if tasks.get(task_id) == (-neg_pri, seq):  # seq is unique per submission
                return
            heapq.heappop(heap)

    def pop(self):
        self._purge()
        if not self._heap:
            raise IndexError("pop from empty scheduler")
        _, _, task_id = heapq.heappop(self._heap)
        del self._tasks[task_id]
        return task_id

    def peek(self):
        self._purge()
        if not self._heap:
            raise IndexError("peek from empty scheduler")
        return self._heap[0][2]

    def priority_of(self, task_id):
        try:
            return self._tasks[task_id][0]
        except KeyError:
            raise KeyError(task_id) from None

    def __len__(self):
        return len(self._tasks)

import unicodedata

_MARK_CATEGORIES = frozenset(("Mn", "Mc", "Me"))


def truncate_display(s: str, width: int) -> str:
    if width < 0:
        raise ValueError("width must be non-negative")
    if width == 0 or not s:
        return ""

    # s[0] always starts unit 1 (even if it is a stray leading combining mark).
    units = 1
    for i in range(1, len(s)):
        if unicodedata.category(s[i]) not in _MARK_CATEGORIES:
            units += 1
            if units > width:
                # s[i] begins the (width+1)-th unit, so everything before
                # it — including the marks of the width-th unit — is kept.
                return s[:i]
    return s

def weighted_median(values: list, weights: list) -> float:
    """Return the lower weighted median of `values` with the given `weights`.

    The lower weighted median is the smallest value v such that the total
    weight of all entries with value <= v reaches W / 2 (within an absolute
    tolerance of 1e-9), where W is the sum of all weights.
    """
    if len(values) != len(weights):
        raise ValueError("values and weights must have the same length")
    if not values:
        raise ValueError("values must not be empty")
    for w in weights:
        if w < 0:
            raise ValueError("weights must be non-negative")

    total = sum(weights)
    if total <= 0:
        raise ValueError("total weight must be positive")

    threshold = total / 2 - 1e-9
    cumulative = 0.0
    for value, weight in sorted(zip(values, weights), key=lambda p: p[0]):
        cumulative += weight
        if cumulative >= threshold:
            return value

    # Unreachable: cumulative ends at `total`, which always exceeds the
    # threshold when total > 0. Kept as a defensive fallback.
    return max(values)

import math


def vector_norm(v: list[float]) -> float:
    """Return the Euclidean (L2) norm of v."""
    for x in v:
        if not math.isfinite(x):
            raise ValueError("vector entries must be finite")

    if not v:
        return 0.0

    scale = max(abs(x) for x in v)
    if scale == 0.0:
        return 0.0

    # Scaling avoids overflow for large entries and underflow for small ones.
    # fsum provides an accurately rounded sum of the normalized squares.
    scaled_square_sum = math.fsum((x / scale) ** 2 for x in v)
    return scale * math.sqrt(scaled_square_sum)

def kth_root_floor(n: int, k: int) -> int:
    """Return floor(n ** (1 / k)) using only integer arithmetic."""
    if n < 0:
        raise ValueError("n must be nonnegative")
    if k < 1:
        raise ValueError("k must be at least 1")

    if n < 2 or k == 1:
        return n

    # Since n < 2**n.bit_length(), k >= bit_length implies 2**k > n.
    if k >= n.bit_length():
        return 1

    bit_length = n.bit_length()

    # n < 2**bit_length, so the k-th root is below
    # 2**ceil(bit_length / k).
    low = 1
    high = 1 << ((bit_length + k - 1) // k)

    # Invariant:
    #   low**k <= n
    #   high**k > n
    while low + 1 < high:
        mid = (low + high) // 2
        if mid**k <= n:
            low = mid
        else:
            high = mid

    return low

def peak_load(intervals: list[tuple[int, int]]) -> tuple[int, int]:
    # Net change in load at each event coordinate.
    delta: dict[int, int] = {}
    for s, e in intervals:
        delta[s] = delta.get(s, 0) + 1
        delta[e] = delta.get(e, 0) - 1

    max_load = 0
    earliest_t = 0
    cur = 0
    for t in sorted(delta):
        cur += delta[t]          # load on [t, next_event) after applying all changes at t
        if cur > max_load:       # strict: keeps the *earliest* time the max is hit
            max_load = cur
            earliest_t = t
    return (max_load, earliest_t)

def parse_duration(text):
    if not isinstance(text, str):
        raise TypeError("expected str for duration text")
    if text == "" or text.isspace():
        raise ValueError("empty duration")

    total_seconds = 0
    last_unit_index = -1
    i = 0
    length = len(text)

    while i < length:
        value = 0
        digits_start = i

        while i < length:
            char_code = ord(text[i])
            if char_code < 48 or char_code > 57:
                break
            value = value * 10 + (char_code - 48)
            i += 1

        if i == digits_start or i == length:
            raise ValueError("malformed duration")

        unit = text[i]
        if unit == "h":
            unit_index = 0
            multiplier = 3600
        elif unit == "m":
            unit_index = 1
            multiplier = 60
        elif unit == "s":
            unit_index = 2
            multiplier = 1
        else:
            raise ValueError("malformed duration")

        if unit_index <= last_unit_index:
            raise ValueError("malformed duration")

        last_unit_index = unit_index
        total_seconds += value * multiplier
        i += 1

    return total_seconds

def clamp_values(values, low, high):
    if not isinstance(values, list):
        raise TypeError("values must be a list")
    if isinstance(low, bool) or not isinstance(low, (int, float)):
        raise TypeError("bounds must be numbers")
    if isinstance(high, bool) or not isinstance(high, (int, float)):
        raise TypeError("bounds must be numbers")
    if low > high:
        raise ValueError("low must not exceed high")

    result = []
    for i, v in enumerate(values):
        if isinstance(v, bool) or not isinstance(v, (int, float)):
            raise TypeError("index " + str(i))
        if v < low:
            result.append(low)
        elif v > high:
            result.append(high)
        else:
            result.append(v)
    return result

def flatten_depth(nested, max_depth):
    # --- Validation, in the required order ---
    if not isinstance(nested, list):
        raise TypeError("nested must be a list")
    if isinstance(max_depth, bool) or not isinstance(max_depth, int):
        raise TypeError("max_depth must be an int")
    if max_depth < 0:
        raise ValueError("max_depth must be >= 0")

    # --- Iterative flatten with an explicit stack ---
    # Depth convention: `nested` itself is depth 0, its direct elements are
    # depth 1, etc. A list at depth d is expanded only when d <= max_depth.
    # With max_depth == 0 nothing is ever expanded, so the result is exactly
    # a shallow copy of `nested`.
    result = []
    stack = [(item, 1) for item in reversed(nested)]
    while stack:
        item, depth = stack.pop()
        if isinstance(item, list) and depth <= max_depth:
            # Push children in reverse so they pop off left-to-right.
            stack.extend((child, depth + 1) for child in reversed(item))
        else:
            result.append(item)
    return result

def summarize_by_category(rows):
    if not isinstance(rows, list):
        raise TypeError("rows must be a list")

    result = {}
    for i, row in enumerate(rows):
        # a. structure check
        if not isinstance(row, tuple) or len(row) != 3:
            raise TypeError(f"row {i} must be a tuple of exactly 3 elements")
        category, amount, refunded = row
        # b. category check
        if not isinstance(category, str) or category == "":
            raise ValueError(f"row {i} has an invalid category")
        # c. amount type check (bool rejected before int/float, since bool subclasses int)
        if isinstance(amount, bool) or not isinstance(amount, (int, float)):
            raise TypeError(f"row {i} has an invalid amount")
        # d. amount value check
        if amount < 0:
            raise ValueError(f"row {i} has a negative amount")
        # e. refunded check
        if not isinstance(refunded, bool):
            raise TypeError(f"row {i} has an invalid refunded flag")

        amount = float(amount)  # guarantees float outputs even for int inputs

        if category in result:
            summary = result[category]
            summary["count"] += 1
            summary["gross"] += amount
            if not refunded:
                summary["net"] += amount
            if amount > summary["largest"]:
                summary["largest"] = amount
        else:
            result[category] = {
                "count": 1,
                "gross": amount,
                "net": 0.0 if refunded else amount,
                "largest": amount,
            }

    return result

def top_k_frequent(items, k):
    if not isinstance(items, list):
        raise TypeError("items must be a list")
    if isinstance(k, bool) or not isinstance(k, int):
        raise TypeError("k must be an int")
    if k < 0:
        raise ValueError("k must be >= 0")

    if k == 0 or not items:
        return []

    tally = {}
    for value in items:
        if value in tally:
            tally[value] = tally[value] + 1
        else:
            tally[value] = 1

    pool = []
    for value in tally:
        pool.append(value)

    out = []
    take = k
    while take > 0 and pool:
        best_i = 0
        best_c = tally[pool[0]]
        i = 1
        while i < len(pool):
            c = tally[pool[i]]
            if c > best_c:
                best_i = i
                best_c = c
            i += 1
        value = pool.pop(best_i)
        out.append((value, tally[value]))
        take -= 1

    return out

def eval_rpn(tokens):
    if not isinstance(tokens, list):
        raise TypeError("tokens must be a list")
    if not tokens:
        raise ValueError("empty expression")

    stack = []

    for i, tok in enumerate(tokens):
        if not isinstance(tok, str):
            raise TypeError(f"token {i} must be a string")

        # Operator ("+" and "-" alone are always operators, never signs).
        if tok == "+" or tok == "-" or tok == "*" or tok == "/":
            if len(stack) < 2:
                raise ValueError(f"stack underflow at token {i}")
            right = stack.pop()
            left = stack.pop()

            if tok == "+":
                result = left + right
            elif tok == "-":
                result = left - right
            elif tok == "*":
                result = left * right
            else:  # tok == "/"
                if right == 0:
                    raise ZeroDivisionError(f"division by zero at token {i}")
                # Truncation toward zero: divide magnitudes, then fix the sign.
                result = abs(left) // abs(right)
                if (left < 0) != (right < 0):
                    result = -result
            stack.append(result)
            continue

        # Operand: optional single leading sign, then >= 1 ASCII digits.
        body = tok
        if body and (body[0] == "+" or body[0] == "-"):
            body = body[1:]
        if not body:
            raise ValueError(f"unknown token {tok!r} at token {i}")

        value = 0
        for ch in body:
            digit = ord(ch) - ord("0")
            if digit < 0 or digit > 9:  # strict ASCII digits only
                raise ValueError(f"unknown token {tok!r} at token {i}")
            value = value * 10 + digit
        if tok[0] == "-":
            value = -value
        stack.append(value)

    if len(stack) > 1:
        raise ValueError("leftover operands")
    return stack[0]

def render_template(template, context):
    if not isinstance(template, str):
        raise TypeError("template must be a string")
    if not isinstance(context, dict):
        raise TypeError("context must be a dict")

    parts = []
    i = 0
    n = len(template)
    while i < n:
        ch = template[i]
        if ch == "{":
            # Escape "{{" -> literal "{"
            if i + 1 < n and template[i + 1] == "{":
                parts.append("{")
                i += 2
                continue
            # Placeholder: scan its name left to right
            p = i
            j = i + 1
            name = []
            while True:
                if j >= n:
                    raise ValueError(
                        "unclosed placeholder at position " + str(p))
                c = template[j]
                if c == "}":
                    break
                if ("a" <= c <= "z") or ("A" <= c <= "Z") \
                        or ("0" <= c <= "9") or c == "_":
                    name.append(c)
                    j += 1
                else:
                    raise ValueError(
                        "invalid placeholder at position " + str(p))
            if not name:
                raise ValueError("empty placeholder at position " + str(p))
            key = "".join(name)
            if key not in context:
                raise KeyError(key)
            parts.append(str(context[key]))
            i = j + 1
        elif ch == "}":
            # Escape "}}" -> literal "}"
            if i + 1 < n and template[i + 1] == "}":
                parts.append("}")
                i += 2
            else:
                raise ValueError("stray '}' at position " + str(i))
        else:
            parts.append(ch)
            i += 1
    return "".join(parts)

def deep_get(data, path):
    if not isinstance(path, str):
        raise TypeError("path must be a string")
    if path == "":
        raise ValueError("path must not be empty")

    segments = path.split(".")
    if "" in segments:
        raise ValueError("empty segment in path")

    def valid_index(text):
        digits = text[1:] if text.startswith("-") else text
        return digits != "" and digits.isascii() and digits.isdigit()

    def walk(node, remaining):
        if not remaining:
            return node

        segment = remaining[0]
        rest = remaining[1:]

        if isinstance(node, dict):
            if segment not in node:
                raise KeyError(segment)
            return walk(node[segment], rest)

        if isinstance(node, list):
            if not valid_index(segment):
                raise ValueError("invalid index: " + segment)
            try:
                index = int(segment)
            except ValueError:
                raise IndexError(segment) from None
            try:
                value = node[index]
            except IndexError:
                raise IndexError(segment) from None
            return walk(value, rest)

        raise TypeError("cannot descend into " + type(node).__name__)

    return walk(data, segments)
